#!/usr/bin/env python3
import sys, os, shutil, pathlib

HELP_TEXT = """Usage: ./executable [options]

Options:
    -d, --default TEXT  text inserted into the textfield on startup
    -o, --out-file FILE write final command to file
        --in-file FILE  read initial command from file
        --config-reference 
                        print out the default configuration file
    -r, --raw-mode      keep linebreaks in finished command when closing
        --no-isolation  disable isolation. This will run the commands directly
                        on your system, without protection. Take care.
    -h, --help          print this help menu
"""

# Load config reference from file if exists else hardcode
try:
    CONFIG_REF = open('/tmp/c_out','rb').read().decode('utf-8')
except:
    CONFIG_REF = """\n#  ____  _
# |  _ \\(_)_ __  _ __       .________.
# | |_) | | '_ \\| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"

"""

BWRAP_MSG = "bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode\n"

def error_unrecognized(name):
    sys.stderr.write(f"./executable: Unrecognized option: '{name}'\n")
    sys.exit(1)

def error_missing(name):
    sys.stderr.write(f"./executable: Argument to option '{name}' missing\n")
    sys.exit(1)

def error_duplicate(name):
    sys.stderr.write(f"./executable: Option '{name}' given more than once\n")
    sys.exit(1)

def parse_args(argv):
    args = argv[1:]
    res = {
        "default": None,
        "out_file": None,
        "in_file": None,
        "config_ref": False,
        "raw": False,
        "no_iso": False,
        "help": False,
    }
    seen = set()
    short_map = {'d': 'default', 'o': 'out-file', 'r': 'raw-mode', 'h': 'help'}
    long_requires_arg = {'default': True, 'out-file': True, 'in-file': True, 'config-reference': False, 'raw-mode': False, 'no-isolation': False, 'help': False}
    i=0
    while i < len(args):
        arg=args[i]
        if arg=="--":
            break
        if arg.startswith("--"):
            if "=" in arg:
                eq=arg.find("=")
                name=arg[2:eq]
                value=arg[eq+1:]
                has_eq=True
            else:
                name=arg[2:]
                value=None
                has_eq=False
            if name=="":
                error_unrecognized(name)
            if name not in long_requires_arg:
                error_unrecognized(name)
            if name in seen:
                error_duplicate(name)
            seen.add(name)
            if long_requires_arg[name]:
                if has_eq:
                    val=value
                else:
                    i+=1
                    if i>=len(args):
                        error_missing(name)
                    val=args[i]
                if name=="default":
                    res["default"]=val
                elif name=="out-file":
                    res["out_file"]=val
                elif name=="in-file":
                    res["in_file"]=val
            else:
                if name=="config-reference":
                    res["config_ref"]=True
                elif name=="raw-mode":
                    res["raw"]=True
                elif name=="no-isolation":
                    res["no_iso"]=True
                elif name=="help":
                    res["help"]=True
        elif arg.startswith("-") and len(arg)>1:
            j=1
            while j < len(arg):
                ch=arg[j]
                if ch not in short_map:
                    error_unrecognized(ch)
                long_name=short_map[ch]
                if long_name in seen:
                    error_duplicate(long_name)
                seen.add(long_name)
                requires=long_requires_arg.get(long_name, False)
                if requires:
                    if j+1 < len(arg):
                        val=arg[j+1:]
                        if long_name=="default":
                            res["default"]=val
                        elif long_name=="out-file":
                            res["out_file"]=val
                        j=len(arg)
                        break
                    else:
                        i+=1
                        if i>=len(args):
                            error_missing(ch)
                        val=args[i]
                        if long_name=="default":
                            res["default"]=val
                        elif long_name=="out-file":
                            res["out_file"]=val
                        break
                else:
                    if long_name=="raw-mode":
                        res["raw"]=True
                    elif long_name=="help":
                        res["help"]=True
                    j+=1
        else:
            pass
        i+=1
    if res["help"]:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    if res["config_ref"]:
        sys.stdout.write(CONFIG_REF)
        sys.exit(0)
    return res

def main():
    opts=parse_args(sys.argv)
    if opts["in_file"] is not None:
        p=opts["in_file"]
        if not os.path.exists(p) or not os.path.isfile(p):
            sys.stderr.write("Error: No such file or directory (os error 2)\n")
            sys.exit(1)
        try:
            data=open(p,'r').read()
        except:
            sys.stderr.write("Error: No such file or directory (os error 2)\n")
            sys.exit(1)
        initial_text=data
    else:
        initial_text=opts["default"] if opts["default"] is not None else ""
    if not opts["no_iso"]:
        if shutil.which("bwrap") is None:
            sys.stdout.write(BWRAP_MSG)
            sys.exit(1)
    if not sys.stdout.isatty() or not sys.stdin.isatty():
        sys.stderr.write("\x1b[?1049hError: No such device or address (os error 6)\n")
        sys.exit(1)
    import curses
    config_dir=os.path.expanduser("~/.config/pipr")
    config_path=os.path.join(config_dir,"pipr.toml")
    config={
        "finish_hook": None,
        "paranoid_history_mode_default": False,
        "autoeval_mode_default": True,
        "history_size": 500,
        "cmdlist_always_show_preview": False,
        "cmd_timeout_millis": 2000,
        "highlighting_enabled": True,
        "eval_environment": ["bash", "-c"],
        "snippets": {"s": " | sed -r 's/||//g'"},
        "help_viewers": {"m": "man ??", "h": "?? --help | less"},
        "output_viewers": {"l": "less"},
    }
    if os.path.exists(config_path):
        try:
            import tomli
            with open(config_path,"rb") as f:
                loaded=tomli.load(f)
            for k in ["finish_hook","paranoid_history_mode_default","autoeval_mode_default","history_size","cmdlist_always_show_preview","cmd_timeout_millis","highlighting_enabled","eval_environment"]:
                if k in loaded:
                    config[k]=loaded[k]
            if "snippets" in loaded and isinstance(loaded["snippets"],dict):
                config["snippets"]=loaded["snippets"]
            if "help_viewers" in loaded and isinstance(loaded["help_viewers"],dict):
                config["help_viewers"]=loaded["help_viewers"]
            if "output_viewers" in loaded and isinstance(loaded["output_viewers"],dict):
                config["output_viewers"]=loaded["output_viewers"]
        except Exception:
            pass
    else:
        try:
            os.makedirs(config_dir, exist_ok=True)
            with open(config_path,"w") as f:
                f.write(CONFIG_REF)
        except:
            pass

    def evaluate_command(cmd_text, raw_mode, eval_env, timeout_ms):
        lines=cmd_text.split("\n")
        filtered=[]
        for line in lines:
            if line.lstrip().startswith("#"):
                continue
            filtered.append(line)
        if raw_mode:
            exec_cmd="\n".join(filtered)
        else:
            exec_cmd=" ".join(filtered)
        exec_cmd=exec_cmd.strip()
        if not exec_cmd:
            return "", "", 0, False
        try:
            import subprocess
            timeout=timeout_ms/1000.0
            proc=subprocess.run(eval_env+[exec_cmd], capture_output=True, text=True, timeout=timeout)
            return proc.stdout, proc.stderr, proc.returncode, False
        except subprocess.TimeoutExpired as e:
            stdout = e.stdout.decode() if isinstance(e.stdout, bytes) else (e.stdout or "")
            if isinstance(stdout, bytes):
                try:
                    stdout=stdout.decode()
                except:
                    stdout=""
            return stdout, "Command timed out", 124, True
        except Exception as e:
            return "", str(e), 1, False

    history_path=os.path.join(config_dir,"history")
    bookmarks_path=os.path.join(config_dir,"bookmarks")

    def load_list_file(path):
        if not os.path.exists(path):
            return []
        try:
            content=open(path,'r').read()
            if not content:
                return []
            parts=content.split("\n---\n")
            return [p for p in parts if p!=""]
        except:
            return []

    def save_list_file(path, items, max_size):
        try:
            if len(items)>max_size:
                items=items[-max_size:]
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path,'w') as f:
                f.write("\n---\n".join(items))
        except:
            pass

    final_command=None

    def tui_main(stdscr):
        nonlocal final_command
        curses.curs_set(1)
        stdscr.keypad(True)
        if config.get("highlighting_enabled"):
            try:
                curses.start_color()
                curses.use_default_colors()
            except:
                pass

        cmd_text=initial_text
        cursor=len(cmd_text)
        autoeval=config.get("autoeval_mode_default", True)
        paranoid=config.get("paranoid_history_mode_default", False)
        history=load_list_file(history_path)
        hist_index=len(history)
        hist_temp=None
        bookmarks=load_list_file(bookmarks_path)
        cache_enabled=False
        cache_prefix=None
        cache_output=None
        cache_pipe_pos=None
        out_text=""
        err_text=""
        last_rc=0
        show_help=False
        show_history=False
        history_selected=0
        show_bookmarks=False
        bookmarks_selected=0
        show_snippets=False
        show_output_viewers=False
        show_help_viewers=False
        timeout_ms=config.get("cmd_timeout_millis", 2000)
        eval_env=config.get("eval_environment", ["bash","-c"])
        opts_raw=opts["raw"]

        def get_tags():
            tags=[]
            if cmd_text in bookmarks:
                tags.append("[Bookmarked]")
            if autoeval:
                tags.append("[Autoeval]")
            if cache_enabled:
                tags.append("[Caching]")
            if paranoid and autoeval:
                tags.append("[Paranoid]")
            return tags

        def draw():
            stdscr.clear()
            h,w=stdscr.getmaxyx()
            tags=get_tags()
            title=" Command"
            if tags:
