                top=top[:w]
            try:
                stdscr.addstr(0,0,top)
            except:
                pass
            for idx,line in enumerate(cmd_lines):
                cw=w-4
                disp=line[:cw]
                padded=disp+" "*(cw-len(disp))
                try:
                    stdscr.addstr(1+idx,0,f" │{padded}│")
                except:
                    pass
            try:
                stdscr.addstr(1+len(cmd_lines),0," └"+"─"*(w-4)+"┘")
            except:
                pass
            out_start=1+len(cmd_lines)+1
            has_output=out_text!="" or err_text!=""
            out_title=" Output [+] " if not has_output else " Output "
