                            finally:
                                stdscr.clear()
                                curses.reset_prog_mode()
                                curses.curs_set(1)
                                show_output_viewers=False
                                show_help_viewers=False
                                draw()
                                continue
                        else:
                            before=cmd_text[:cursor]
                            after=cmd_text[cursor:]
                            start=cursor
                            while start>0 and cmd_text[start-1] not in " \t\n|;":
                                start-=1
                            end=cursor
                            while end < len(cmd_text) and cmd_text[end] not in " \t\n|;":
                                end+=1
                            word=cmd_text[start:end].strip()
