                if key==27:
                    show_output_viewers=False
                    show_help_viewers=False
                    draw()
                    continue
                if show_output_viewers or show_help_viewers:
                    draw()
                    continue

            if show_history:
                if isinstance(key,str) and key=='\x1b':
