                        bookmarks_selected+=1
                    draw()
                    continue
                elif key=='\n' or key=='\r' or key==curses.KEY_ENTER or (isinstance(key,int) and key==10):
                    if 0 <= bookmarks_selected < len(bookmarks):
                        cmd_text=bookmarks[bookmarks_selected]
