                    draw()
                    continue
                continue

            if key==curses.KEY_F1 or (isinstance(key,int) and key==265):
                show_help=not show_help
                draw()
                continue
            if key==curses.KEY_F2 or (isinstance(key,int) and key==266):
                autoeval=not autoeval
                draw()
                continue
            if key==curses.KEY_F3 or (isinstance(key,int) and key==267):
                paranoid=not paranoid
                draw()
                continue
            if key==curses.KEY_F4 or (isinstance(key,int) and key==268):
                show_history=True
                history_selected=0
                history=load_list_file(history_path)
                draw()
                continue
            if key==curses.KEY_F5 or (isinstance(key,int) and key==269):
