    sys.stderr.write(f"./executable: Option '{name}' given more than once\n")
    sys.exit(1)

def parse_args(argv):
    args = argv[1:]
    res = {"default": None, "out_file": None, "in_file": None, "config_ref": False, "raw": False, "no_iso": False, "help": False}
    seen=set()
    short_map={'d':'default','o':'out-file','r':'raw-mode','h':'help'}
    long_requires_arg={'default':True,'out-file':True,'in-file':True,'config-reference':False,'raw-mode':False,'no-isolation':False,'help':False}
    i=0
    while i < len(args):
        arg=args[i]
        if arg=="--":
            break
        if arg.startswith("--"):
            if "=" in arg:
                eq=arg.find("=")
                name=arg[2:eq]
                value=arg[eq+1:]
                has_eq=True
            else:
                name=arg[2:]
                value=None
                has_eq=False
            if name=="":
                error_unrecognized(name)
            if name not in long_requires_arg:
                error_unrecognized(name)
            if name in seen:
                error_duplicate(name)
            seen.add(name)
            if long_requires_arg[name]:
                if has_eq:
                    val=value
                else:
