                err_lines=err_text.split("\n")
                err_content_start=err_start+1
                max_err=h-err_content_start-2
                for i in range(min(len(err_lines), max_err-1)):
                    line=err_lines[i][:w-4]
                    padded=line+" "*(w-4-len(line))
                    try:
                        stdscr.addstr(err_content_start+i,0,f" │{padded}│")
                    except:
