                        else:
                            try:
                                stdscr.addstr(sy+1+i,sx,f"│{entry.ljust(pw-4)}│")
                            except:
                                pass
                    else:
                        try:
                            stdscr.addstr(sy+1+i,sx,f"│{' '*(pw-4)}│")
                        except:
                            pass
                try:
                    stdscr.addstr(sy+ph-1,sx,"└"+"─"*(pw-2)+"┘")
                except:
                    pass
            if show_bookmarks:
                ph=min(h-2, len(bookmarks)+2)
                pw=w-4
                sy=1
                sx=2
                title_b=" Bookmarks "
                try:
                    stdscr.addstr(sy,sx,"┌"+title_b+"─"*(pw-len(title_b)-2)+"┐")
                except:
                    pass
                for i in range(ph-2):
                    if i < len(bookmarks):
                        entry=bookmarks[i].replace("\n"," ")
                        if len(entry)>pw-4:
                            entry=entry[:pw-7]+"..."
                        if i==bookmarks_selected:
                            try:
                                stdscr.addstr(sy+1+i,sx,f"│{entry.ljust(pw-4)}│", curses.A_REVERSE)
                            except:
                                pass
                        else:
                            try:
                                stdscr.addstr(sy+1+i,sx,f"│{entry.ljust(pw-4)}│")
                            except:
                                pass
                    else:
                        try:
                            stdscr.addstr(sy+1+i,sx,f"│{' '*(pw-4)}│")
                        except:
                            pass
                try:
                    stdscr.addstr(sy+ph-1,sx,"└"+"─"*(pw-2)+"┘")
                except:
                    pass
            if show_snippets:
                snippets=config.get("snippets",{})
                ph=min(h-2, len(snippets)+2)
                pw=80
                sy=1
                sx=2
                title_s=" Open in "
                try:
                    stdscr.addstr(sy,sx,"┌"+title_s+"─"*(pw-len(title_s)-2)+"┐")
                except:
                    pass
                for i,(k,v) in enumerate(snippets.items()):
                    if i>=ph-2:
                        break
                    line=f"{k}: {v}"
                    if len(line)>pw-4:
                        line=line[:pw-7]+"..."
                    try:
                        stdscr.addstr(sy+1+i,sx,f"│{line.ljust(pw-4)}│")
                    except:
                        pass
                try:
                    stdscr.addstr(sy+ph-1,sx,"└"+"─"*(pw-2)+"┘")
                except:
                    pass
            if show_output_viewers or show_help_viewers:
                if show_output_viewers:
                    viewers=config.get("output_viewers",{})
                else:
                    viewers=config.get("help_viewers",{})
                ph=min(h-2, len(viewers)+2)
                pw=60
                sy=1
                sx=2
                title_v=" Open in "
                try:
                    stdscr.addstr(sy,sx,"┌"+title_v+"─"*(pw-len(title_v)-2)+"┐")
                except:
                    pass
                for i,(k,v) in enumerate(viewers.items()):
                    if i>=ph-2:
                        break
                    line=f"{k}: {v}"
                    try:
                        stdscr.addstr(sy+1+i,sx,f"│{line.ljust(pw-4)}│")
                    except:
                        pass
                try:
                    stdscr.addstr(sy+ph-1,sx,"└"+"─"*(pw-2)+"┘")
                except:
                    pass
            before=cmd_text[:cursor]
            line_idx=before.count("\n")
            if "\n" in before:
                col_idx=len(before.split("\n")[-1])
            else:
                col_idx=len(before)
            cur_y=1+line_idx
            cur_x=2+col_idx
            try:
                stdscr.move(cur_y,cur_x)
            except:
                pass
            stdscr.refresh()

        def do_evaluate():
            nonlocal out_text, err_text, last_rc, cache_output, cache_prefix, cache_enabled, cache_pipe_pos
            if cache_enabled and cache_prefix is not None and cache_pipe_pos is not None:
                if len(cmd_text)>cache_pipe_pos and cmd_text[cache_pipe_pos]=='|':
                    cur_prefix=cmd_text[:cache_pipe_pos]
                    if cur_prefix==cache_prefix:
                        suffix=cmd_text[cache_pipe_pos+1:]
                        if opts_raw:
                            suffix_exec="\n".join([l for l in suffix.split("\n") if not l.lstrip().startswith("#")])
                        else:
                            suffix_exec=" ".join([l for l in suffix.split("\n") if not l.lstrip().startswith("#")])
                        suffix_exec=suffix_exec.strip()
                        if suffix_exec=="":
                            out_text=cache_output
                            err_text=""
                            last_rc=0
                            return
                        try:
                            import subprocess
                            timeout=timeout_ms/1000.0
                            proc=subprocess.run(eval_env+[suffix_exec], input=cache_output, capture_output=True, text=True, timeout=timeout)
                            out_text=proc.stdout
                            err_text=proc.stderr
                            last_rc=proc.returncode
                            return
                        except subprocess.TimeoutExpired as e:
                            stdout = e.stdout.decode() if isinstance(e.stdout, bytes) else (e.stdout or "")
                            if isinstance(stdout, bytes):
                                try:
                                    stdout=stdout.decode()
                                except:
                                    stdout=""
                            out_text=stdout
                            err_text="Command timed out"
                            last_rc=124
                            return
                        except Exception as e:
                            out_text=""
                            err_text=str(e)
                            last_rc=1
                            return
                    else:
                        cache_enabled=False
                        cache_prefix=None
                        cache_output=None
                        cache_pipe_pos=None
                else:
                    cache_enabled=False
                    cache_prefix=None
                    cache_output=None
                    cache_pipe_pos=None
            stdout,stderr,rc,to=evaluate_command(cmd_text, opts_raw, eval_env, timeout_ms)
            out_text=stdout
            err_text=stderr
            last_rc=rc

        draw()
        while True:
            try:
                key=stdscr.get_wch()
            except:
                try:
                    k=stdscr.getch()
                    if k==-1:
                        continue
                    if 0<=k<=255:
                        key=chr(k)
                    else:
                        key=k
                except:
                    continue

            if show_snippets:
                if isinstance(key,str):
                    if key=='\x1b':
                        show_snippets=False
                        draw()
                        continue
                    snippets=config.get("snippets",{})
                    if key in snippets:
                        snippet=snippets[key]
                        ph_idx=snippet.find("||")
                        if ph_idx!=-1:
                            insert_text=snippet.replace("||","")
                            before=cmd_text[:cursor]
                            after=cmd_text[cursor:]
                            cmd_text=before+insert_text+after
                            cursor=len(before)+ph_idx
                        else:
                            before=cmd_text[:cursor]
                            after=cmd_text[cursor:]
                            cmd_text=before+snippet+after
                            cursor=len(before)+len(snippet)
                        show_snippets=False
                        if autoeval:
                            do_evaluate()
                            if paranoid and last_rc==0:
                                history.append(cmd_text)
                                save_list_file(history_path, history, config.get("history_size",500))
                        draw()
                        continue
                elif key==27:
                    show_snippets=False
                    draw()
                    continue
                if show_snippets:
                    draw()
                    continue

            if show_output_viewers or show_help_viewers:
                if isinstance(key,str):
                    if key=='\x1b':
                        show_output_viewers=False
                        show_help_viewers=False
                        draw()
                        continue
                    viewers=config.get("output_viewers",{}) if show_output_viewers else config.get("help_viewers",{})
                    if key in viewers:
                        viewer_cmd=viewers[key]
                        if show_output_viewers:
                            try:
                                curses.def_prog_mode()
                                curses.endwin()
                                import tempfile, os
                                with tempfile.NamedTemporaryFile(mode='w', delete=False) as tf:
                                    tf.write(out_text)
                                    temp_name=tf.name
                                if viewer_cmd.strip()=="less":
                                    os.system(f"less {temp_name}")
                                else:
                                    os.system(f"cat {temp_name} | {viewer_cmd}")
                                os.unlink(temp_name)
                            except:
                                pass
                            finally:
                                stdscr.clear()
                                curses.reset_prog_mode()
                                curses.curs_set(1)
                                show_output_viewers=False
                                show_help_viewers=False
                                draw()
                                continue
                        else:
                            before=cmd_text[:cursor]
                            after=cmd_text[cursor:]
                            start=cursor
                            while start>0 and cmd_text[start-1] not in " \t\n|;":
                                start-=1
                            end=cursor
                            while end < len(cmd_text) and cmd_text[end] not in " \t\n|;":
                                end+=1
                            word=cmd_text[start:end].strip()
                            cmd_to_run=viewer_cmd.replace("??",word)
                            try:
                                curses.def_prog_mode()
                                curses.endwin()
                                os.system(cmd_to_run)
                            except:
                                pass
                            finally:
                                stdscr.clear()
                                curses.reset_prog_mode()
                                curses.curs_set(1)
                                show_help_viewers=False
                                show_output_viewers=False
                                draw()
                                continue
                if key==27:
                    show_output_viewers=False
                    show_help_viewers=False
                    draw()
                    continue
                if show_output_viewers or show_help_viewers:
                    draw()
                    continue

            if show_history:
                if isinstance(key,str) and key=='\x1b':
                    show_history=False
                    draw()
                    continue
                if key==curses.KEY_UP:
                    if history_selected>0:
                        history_selected-=1
                    draw()
                    continue
                elif key==curses.KEY_DOWN:
                    if history_selected < len(history)-1:
                        history_selected+=1
                    draw()
                    continue
                elif key=='\n' or key=='\r' or key==curses.KEY_ENTER or (isinstance(key,int) and key==10):
                    if 0 <= history_selected < len(history):
                        cmd_text=history[history_selected]
                        cursor=len(cmd_text)
                        show_history=False
                        if autoeval:
                            do_evaluate()
                        draw()
                        continue
                elif key==27:
                    show_history=False
                    draw()
                    continue
                continue

            if show_bookmarks:
                if isinstance(key,str) and key=='\x1b':
                    show_bookmarks=False
                    draw()
                    continue
                if key==curses.KEY_UP:
                    if bookmarks_selected>0:
                        bookmarks_selected-=1
                    draw()
                    continue
                elif key==curses.KEY_DOWN:
                    if bookmarks_selected < len(bookmarks)-1:
                        bookmarks_selected+=1
                    draw()
                    continue
                elif key=='\n' or key=='\r' or key==curses.KEY_ENTER or (isinstance(key,int) and key==10):
                    if 0 <= bookmarks_selected < len(bookmarks):
                        cmd_text=bookmarks[bookmarks_selected]
                        cursor=len(cmd_text)
                        show_bookmarks=False
                        if autoeval:
                            do_evaluate()
                        draw()
                        continue
                elif key==27:
                    show_bookmarks=False
                    draw()
                    continue
                continue

            if show_help:
                if key==curses.KEY_F1 or (isinstance(key,int) and key==265):
                    show_help=False
                    draw()
                    continue
                if isinstance(key,str) and key=='\x1b' or key==27:
                    show_help=False
                    draw()
                    continue
                continue

            if key==curses.KEY_F1 or (isinstance(key,int) and key==265):
                show_help=not show_help
                draw()
                continue
            if key==curses.KEY_F2 or (isinstance(key,int) and key==266):
                autoeval=not autoeval
                draw()
                continue
            if key==curses.KEY_F3 or (isinstance(key,int) and key==267):
                paranoid=not paranoid
                draw()
                continue
            if key==curses.KEY_F4 or (isinstance(key,int) and key==268):
                show_history=True
                history_selected=0
                history=load_list_file(history_path)
                draw()
                continue
            if key==curses.KEY_F5 or (isinstance(key,int) and key==269):
                show_help_viewers=True
                draw()
                continue
            if key==curses.KEY_F6 or (isinstance(key,int) and key==270):
                show_output_viewers=True
                draw()
                continue
            if key==curses.KEY_F7 or (isinstance(key,int) and key==271):
                if cursor < len(cmd_text) and cmd_text[cursor]=='|':
                    prefix=cmd_text[:cursor]
                    stdout,stderr,rc,to=evaluate_command(prefix, opts_raw, eval_env, timeout_ms)
                    if rc==0:
                        cache_enabled=True
                        cache_prefix=prefix
                        cache_output=stdout
                        cache_pipe_pos=cursor
                draw()
