            if isinstance(key,str) and key=='\x02':
                show_bookmarks=True
                bookmarks_selected=0
                bookmarks=load_list_file(bookmarks_path)
                draw()
                continue
            if isinstance(key,str) and key=='\x13':
                if cmd_text in bookmarks:
                    bookmarks=[b for b in bookmarks if b!=cmd_text]
                else:
                    bookmarks.append(cmd_text)
                save_list_file(bookmarks_path, bookmarks, config.get("history_size",500))
                draw()
                continue
            if isinstance(key,str) and key=='\x16':
                show_snippets=True
                draw()
                continue
            if isinstance(key,str) and key=='\x15':
                cmd_text=""
                cursor=0
                out_text=""
                err_text=""
                if cache_enabled:
                    cache_enabled=False
                    cache_prefix=None
                    cache_output=None
                    cache_pipe_pos=None
                if autoeval:
                    do_evaluate()
                draw()
                continue
            if isinstance(key,str) and key=='\x10':
                if history:
                    if hist_index>0:
                        if hist_index==len(history):
                            hist_temp=cmd_text
