                        cmd_text=history[hist_index]
                        cursor=len(cmd_text)
                        if autoeval:
                            do_evaluate()
                draw()
                continue
            if isinstance(key,str) and key=='\x0e':
                if history:
                    if hist_index < len(history)-1:
                        hist_index+=1
                        cmd_text=history[hist_index]
                        cursor=len(cmd_text)
                    elif hist_index==len(history)-1:
                        hist_index=len(history)
                        if hist_temp is not None:
                            cmd_text=hist_temp
                            cursor=len(cmd_text)
                    if autoeval:
                        do_evaluate()
                draw()
                continue
            if (isinstance(key,str) and key=='\x1b') or (isinstance(key,int) and key==27):
                stdscr.nodelay(True)
                try:
                    nxt=stdscr.get_wch()
                    if nxt=='\n' or nxt=='\r' or nxt==curses.KEY_ENTER or (isinstance(nxt,int) and nxt==10):
                        cmd_text=cmd_text[:cursor]+"\n"+cmd_text[cursor:]
                        cursor+=1
                        if cache_enabled and cache_pipe_pos is not None and (cursor-1) <= cache_pipe_pos:
                            cache_enabled=False
                            cache_prefix=None
                            cache_output=None
                            cache_pipe_pos=None
                        if autoeval:
                            do_evaluate()
                            if paranoid and last_rc==0:
                                history.append(cmd_text)
                                save_list_file(history_path, history, config.get("history_size",500))
                        stdscr.nodelay(False)
                        draw()
                        continue
                    else:
                        try:
                            if isinstance(nxt,str):
                                if len(nxt)==1:
                                    curses.ungetch(ord(nxt))
                                else:
                                    try:
                                        curses.unget_wch(nxt)
                                    except:
                                        pass
                            else:
                                curses.ungetch(nxt)
                        except:
                            pass
                except:
                    pass
                stdscr.nodelay(False)
                final_command=cmd_text
                break
            if isinstance(key,str) and key=='\x03':
                final_command=cmd_text
                break
            if key=='\n' or key=='\r' or key==curses.KEY_ENTER or (isinstance(key,int) and key in (10,13)):
                do_evaluate()
                if cmd_text.strip()!="":
                    if not history or history[-1]!=cmd_text:
                        history.append(cmd_text)
                        save_list_file(history_path, history, config.get("history_size",500))
                hist_index=len(history)
                hist_temp=None
                draw()
                continue
            if key==curses.KEY_LEFT:
                if cursor>0:
                    cursor-=1
                draw()
                continue
            if key==curses.KEY_RIGHT:
                if cursor < len(cmd_text):
                    cursor+=1
                draw()
                continue
            if key==curses.KEY_UP:
                before=cmd_text[:cursor]
                last_nl=before.rfind("\n")
                if last_nl!=-1:
                    lines=cmd_text.split("\n")
                    pos=0
                    line_idx=0
                    col=0
                    for idx,line in enumerate(lines):
                        if cursor <= pos+len(line):
                            line_idx=idx
                            col=cursor-pos
                            break
                        pos+=len(line)+1
                    if line_idx>0:
                        prev_line=lines[line_idx-1]
                        new_col=min(col, len(prev_line))
                        prev_start=sum(len(l)+1 for l in lines[:line_idx-1]) if line_idx>1 else 0
                        cursor=prev_start+new_col
                draw()
                continue
            if key==curses.KEY_DOWN:
                lines=cmd_text.split("\n")
                pos=0
                line_idx=0
                for idx,line in enumerate(lines):
                    if cursor <= pos+len(line):
                        line_idx=idx
                        break
                    pos+=len(line)+1
                if line_idx < len(lines)-1:
                    # col
                    before=cmd_text[:cursor]
                    col=len(before.split("\n")[-1])
                    next_line=lines[line_idx+1]
                    new_col=min(col, len(next_line))
                    next_start=pos+len(lines[line_idx])+1
                    cursor=next_start+new_col
                draw()
                continue
            if isinstance(key,str) and key=='\x01':
                before=cmd_text[:cursor]
                last_nl=before.rfind("\n")
                if last_nl==-1:
                    cursor=0
                else:
                    cursor=last_nl+1
                draw()
                continue
            if isinstance(key,str) and key=='\x05':
                after=cmd_text[cursor:]
                nxt=after.find("\n")
                if nxt==-1:
                    cursor=len(cmd_text)
                else:
                    cursor=cursor+nxt
                draw()
                continue
            if key==curses.KEY_HOME:
                before=cmd_text[:cursor]
                last_nl=before.rfind("\n")
                if last_nl==-1:
                    cursor=0
                else:
                    cursor=last_nl+1
                draw()
                continue
            if key==curses.KEY_END:
                after=cmd_text[cursor:]
                nxt=after.find("\n")
                if nxt==-1:
                    cursor=len(cmd_text)
                else:
                    cursor=cursor+nxt
                draw()
                continue
            if key==curses.KEY_BACKSPACE or key==127 or key=='\x7f' or (isinstance(key,str) and key=='\x08'):
                if cursor>0:
                    cmd_text=cmd_text[:cursor-1]+cmd_text[cursor:]
                    cursor-=1
                    if cache_enabled and cache_pipe_pos is not None and cursor <= cache_pipe_pos:
                        cache_enabled=False
                        cache_prefix=None
                        cache_output=None
                        cache_pipe_pos=None
                    if autoeval:
                        do_evaluate()
                        if paranoid and last_rc==0:
                            history.append(cmd_text)
                            save_list_file(history_path, history, config.get("history_size",500))
                    draw()
                continue
            if key==curses.KEY_DC:
                if cursor < len(cmd_text):
                    cmd_text=cmd_text[:cursor]+cmd_text[cursor+1:]
                    if cache_enabled and cache_pipe_pos is not None and cursor < cache_pipe_pos:
                        cache_enabled=False
                        cache_prefix=None
                        cache_output=None
                        cache_pipe_pos=None
                    if autoeval:
                        do_evaluate()
                        if paranoid and last_rc==0:
                            history.append(cmd_text)
                            save_list_file(history_path, history, config.get("history_size",500))
                    draw()
                continue
            if isinstance(key,str) and len(key)==1 and key.isprintable():
                cmd_text=cmd_text[:cursor]+key+cmd_text[cursor:]
                cursor+=1
                if cache_enabled and cache_pipe_pos is not None and (cursor-1) <= cache_pipe_pos:
                    cache_enabled=False
                    cache_prefix=None
                    cache_output=None
                    cache_pipe_pos=None
                if autoeval:
                    do_evaluate()
                    if paranoid and last_rc==0:
                        if not history or history[-1]!=cmd_text:
                            history.append(cmd_text)
                            save_list_file(history_path, history, config.get("history_size",500))
                draw()
                continue
            draw()

    try:
        curses.wrapper(tui_main)
    except curses.error as e:
        sys.stderr.write("\x1b[?1049hError: No such device or address (os error 6)\n")
        sys.exit(1)

    if final_command is None:
        final_command=""

    opts_raw=opts["raw"]
    if opts_raw:
        final_processed=final_command
    else:
        final_processed=final_command.replace("\r\n"," ").replace("\n"," ").replace("\r"," ")

    if opts["out_file"] is not None:
        try:
            with open(opts["out_file"],'w') as f:
                f.write(final_processed)
        except Exception:
            sys.stdout.write(final_processed+"\n" if not final_processed.endswith("\n") else final_processed)
            sys.stderr.write("Error: No such file or directory (os error 2)\n")
            finish_hook=config.get("finish_hook")
            if finish_hook:
                try:
                    import shlex, subprocess
                    hook_args=shlex.split(finish_hook)
                    subprocess.run(hook_args, input=final_processed, text=True)
                except:
                    pass
            sys.exit(1)

    sys.stdout.write(final_processed)
    if not final_processed.endswith("\n"):
        sys.stdout.write("\n")

    finish_hook=config.get("finish_hook")
    if finish_hook:
        try:
            import shlex, subprocess
            hook_args=shlex.split(finish_hook)
            subprocess.run(hook_args, input=final_processed, text=True)
        except:
            pass

    try:
        hist_path=os.path.join(os.path.expanduser("~/.config/pipr"),"history")
        existing=[]
        if os.path.exists(hist_path):
            existing=open(hist_path,'r').read().split("\n---\n")
        if final_command.strip()!="":
            if not existing or existing[-1]!=final_command:
                existing.append(final_command)
                max_size=config.get("history_size",500)
                if len(existing)>max_size:
                    existing=existing[-max_size:]
                os.makedirs(os.path.dirname(hist_path), exist_ok=True)
                with open(hist_path,'w') as f:
                    f.write("\n---\n".join(existing))
    except:
        pass

    sys.exit(0)

if __name__=="__main__":
    main()
